// Static semantic content adapted from the attached 19 October 2026 tutorial.
// No executable HTML or standalone practice inspector is embedded.
export type LessonNode = string | {tag:string; children:LessonNode[]; href?:string};
export interface Lesson {id:string;title:string;content:LessonNode[]}
export const lessons:Lesson[] = [
  {"id":"lesson-0","title":"Start here","content":[{"tag":"h1","children":["GERT Studio tutorial"]},{"tag":"p","children":["Review draft • GERT Studio 0.2.0 Windows preview • updated 19 October 2026"]},{"tag":"p","children":["Build a quality-control process, add uncertainty and rework, simulate it, and save the network. Then extend the same ideas to parallel work and synchronization. No prior GERT knowledge is required."]},{"tag":"p","children":["This guide follows the mathematical specification and editor at GitHub ",{"tag":"code","children":["main"]}," commit ",{"tag":"code","children":["52fcd732787d5829d923bf2178594de21704b2dc"]}," (2 October 2026), inspected on 19 October 2026. The published Windows preview is tag ",{"tag":"code","children":["v0.2.0"]},", built from application source ",{"tag":"code","children":["e4d0b26b281803a520c0525fa8f62011b55219f2"]},"; the later main commit adds the Windows build workflow. The numeric values below are deliberate examples you enter yourself, not application defaults. Use one consistent time unit throughout; we will use hours."]},{"tag":"p","children":["Choose a lesson, then load its practice starting point. Your own project stays in memory. Export before refreshing or closing."]}]},
  {"id":"lesson-1","title":"What changed since the previous tutorial","content":[{"tag":"h2","children":["What changed since the previous tutorial"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Now available"]},{"tag":"th","children":["Where to learn it"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Published Windows 0.2.0 preview ZIP"]},{"tag":"td","children":["Installation, Lesson 0A"]}]},{"tag":"tr","children":[{"tag":"td","children":["Node, duration, and outcome documentation with descriptive certainty"]},{"tag":"td","children":["Lesson 15"]}]},{"tag":"tr","children":[{"tag":"td","children":["Importable null placeholders and separate draft/readiness validation"]},{"tag":"td","children":["Lessons 4 and 16"]}]},{"tag":"tr","children":[{"tag":"td","children":["Export/import of saved simulation results and settings"]},{"tag":"td","children":["Lesson 4"]}]},{"tag":"tr","children":[{"tag":"td","children":["P5–P95 percentiles, spread, Monte Carlo SE, and method-specific 95% confidence intervals"]},{"tag":"td","children":["Lesson 8"]}]},{"tag":"tr","children":[{"tag":"td","children":["Resizable panels and saved panel-size preferences"]},{"tag":"td","children":["Lesson 12"]}]},{"tag":"tr","children":[{"tag":"td","children":["Engine 0.1.1 and controlled cross-platform Beta-PERT numerics"]},{"tag":"td","children":["Lesson 9"]}]},{"tag":"tr","children":[{"tag":"td","children":["GitHub Actions portable build"]},{"tag":"td","children":["Lesson 0E"]}]}]}]},{"tag":"p","children":["The interface release is 0.2.0; the model schema remains 0.1, and the simulation engine is 0.1.1. Those are separate version numbers. Positive consumable requirements are still mandatory. Deterministic minimum completion time, critical-path analysis, Monte Carlo criticality, and reusable capacity scheduling are not implemented in the baseline simulator. Do not infer availability from a proposal or another local branch."]}]},
  {"id":"lesson-2","title":"Learning route","content":[{"tag":"h2","children":["Learning route"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Part"]},{"tag":"th","children":["Goal"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["0"]},{"tag":"td","children":["Install and verify the application"]}]},{"tag":"tr","children":[{"tag":"td","children":["1–3"]},{"tag":"td","children":["Build and simulate a deterministic inspection"]}]},{"tag":"tr","children":[{"tag":"td","children":["4"]},{"tag":"td","children":["Export and import your network"]}]},{"tag":"tr","children":[{"tag":"td","children":["5–7"]},{"tag":"td","children":["Add pass/fail outcomes, uncertain durations, and a rework loop"]}]},{"tag":"tr","children":[{"tag":"td","children":["8–9"]},{"tag":"td","children":["Interpret results and reproduce runs"]}]},{"tag":"tr","children":[{"tag":"td","children":["10–11"]},{"tag":"td","children":["Model parallel instances and synchronization"]}]},{"tag":"tr","children":[{"tag":"td","children":["12–14"]},{"tag":"td","children":["Use editing tools, troubleshoot, and explore a complete prototype example"]}]},{"tag":"tr","children":[{"tag":"td","children":["15–17"]},{"tag":"td","children":["Write documentation, preserve unknowns, and use the interactive guide"]}]}]}]}]},
  {"id":"lesson-3","title":"0. Get GERT Studio","content":[{"tag":"h2","children":["0. Get GERT Studio"]},{"tag":"p","children":["Repository: ",{"tag":"a","children":["gyudar103/gert-studio"],"href":"https://github.com/gyudar103/gert-studio"},"."]},{"tag":"p","children":["Choose one route. Ordinary Windows users use a packaged application when one is supplied. Developers can run Docker or run the Python backend and JavaScript frontend locally."]},{"tag":"h3","children":["0A. Windows portable application — recommended for Windows users"]},{"tag":"ol","children":[{"tag":"li","children":["Open the ",{"tag":"a","children":["GERT Studio 0.2.0 Windows preview release"],"href":"https://github.com/gyudar103/gert-studio/releases/tag/v0.2.0"},"."]},{"tag":"li","children":["Under ",{"tag":"strong","children":["Assets"]},", download ",{"tag":"strong","children":["GERT-Studio-Windows.zip"]},". GitHub's automatically generated Source code ZIP is not the application."]},{"tag":"li","children":["Extract the entire application ZIP to a folder."]},{"tag":"li","children":["Double-click ",{"tag":"strong","children":["GERT Studio.exe"]}," and keep the control window open."]},{"tag":"li","children":["Your default browser should open the editor. If it does not, use ",{"tag":"strong","children":["Open GERT Studio"]}," in the control window or copy its displayed local address. Use the displayed port; it need not be 5173."]}]},{"tag":"p","children":["No separate Python, Node.js, npm, Git, Docker, WSL, or developer tools are needed. Keep ",{"tag":"code","children":["_internal"]}," beside the EXE and run from the extracted folder, not from inside the ZIP. The application can work offline in your installed browser."]},{"tag":"p","children":["This is a published ",{"tag":"strong","children":["unsigned prerelease"]},", not a final signed release. Its release notes report native Windows tests, but leave fresh-machine/standard-user and browser/security-software checks as manual acceptance items. This tutorial does not claim to have rerun those checks."]},{"tag":"p","children":["To check download integrity, obtain the accompanying ",{"tag":"code","children":["GERT-Studio-Windows.zip.sha256"]}," asset. In PowerShell, run ",{"tag":"code","children":["Get-FileHash .\\GERT-Studio-Windows.zip -Algorithm SHA256"]}," and compare the hash with that asset. A matching checksum verifies bytes against the published checksum; it is not a code signature."]},{"tag":"p","children":["Export your model or results before exiting. Click ",{"tag":"strong","children":["Exit GERT Studio"]}," in the control window to stop the server; closing the browser tab alone does not stop it. Each browser tab has its own editor state. Startup logs are at ",{"tag":"code","children":["%LOCALAPPDATA%\\GERT Studio\\launcher.log"]},"."]},{"tag":"p","children":["For developer packaging instructions, see ",{"tag":"a","children":["WINDOWS_DISTRIBUTION.md"],"href":"https://github.com/gyudar103/gert-studio/blob/52fcd732787d5829d923bf2178594de21704b2dc/docs/WINDOWS_DISTRIBUTION.md"},". Docker is an optional route, not a prerequisite for the portable app."]},{"tag":"h3","children":["0B. Developers: optional Docker"]},{"tag":"p","children":["Install Git and Docker with a running Linux container engine. On Windows or macOS, start Docker Desktop. Open PowerShell on Windows or Terminal on macOS/Linux:"]},{"tag":"pre","children":[{"tag":"code","children":["git clone https://github.com/gyudar103/gert-studio.git\ncd gert-studio\ndocker compose up --build -d\n"]}]},{"tag":"p","children":["The first build needs internet access to obtain images and dependencies. Docker installs the backend and frontend dependencies; host Python and Node are unnecessary."]},{"tag":"p","children":["Open ",{"tag":"a","children":["http://localhost:5173"],"href":"http://localhost:5173"},". Check the services with:"]},{"tag":"pre","children":[{"tag":"code","children":["docker compose ps\n"]}]},{"tag":"p","children":[{"tag":"a","children":["http://localhost:8000/api/health"],"href":"http://localhost:8000/api/health"}," should show ",{"tag":"code","children":["{\"status\":\"ok\"}"]},"."]},{"tag":"p","children":["If you already downloaded the repository source ZIP, extract it and open a terminal in the folder containing ",{"tag":"code","children":["docker-compose.yml"]},". Start with ",{"tag":"code","children":["docker compose up --build -d"]},"; cloning and Git are unnecessary for simply running that copy."]},{"tag":"p","children":["To inspect startup failures:"]},{"tag":"pre","children":[{"tag":"code","children":["docker compose logs --tail=100 backend frontend\n"]}]},{"tag":"p","children":["To stop the application after exporting your work:"]},{"tag":"pre","children":[{"tag":"code","children":["docker compose down\n"]}]},{"tag":"h3","children":["0C. Developers: Python and Node without Docker"]},{"tag":"p","children":["Use Python 3.12 and Node.js 22. Python runs the API; Node/npm runs the frontend. Python alone is insufficient for the complete editor."]},{"tag":"p","children":["Clone the repository as above. In the first terminal, from the repository root:"]},{"tag":"p","children":[{"tag":"strong","children":["Windows PowerShell"]}]},{"tag":"pre","children":[{"tag":"code","children":["cd backend\npy -3.12 -m venv .venv\n.\\.venv\\Scripts\\python.exe -m pip install -r requirements.txt\n.\\.venv\\Scripts\\python.exe -m uvicorn app.main:app --host 127.0.0.1 --port 8000 --reload\n"]}]},{"tag":"p","children":[{"tag":"strong","children":["macOS/Linux"]}]},{"tag":"pre","children":[{"tag":"code","children":["cd backend\npython3.12 -m venv .venv\n.venv/bin/python -m pip install -r requirements.txt\n.venv/bin/python -m uvicorn app.main:app --host 127.0.0.1 --port 8000 --reload\n"]}]},{"tag":"p","children":["Open a second terminal at the repository root:"]},{"tag":"pre","children":[{"tag":"code","children":["cd frontend\nnpm ci\nnpm run dev -- --host 127.0.0.1\n"]}]},{"tag":"p","children":["Open ",{"tag":"a","children":["http://localhost:5173"],"href":"http://localhost:5173"},". The frontend proxies ",{"tag":"code","children":["/api"]}," to the backend on port 8000. Leave both terminals running. To stop, export your work and press Ctrl+C in both terminals."]},{"tag":"p","children":["Native Python 3.12 and Node/npm are the current primary developer tools; Docker remains optional. These commands are derived from the repository configuration, not fresh clean-install testing on all three operating systems."]},{"tag":"h3","children":["0D. Verify the editor"]},{"tag":"p","children":["Click ",{"tag":"strong","children":["Load demo"]},", then ",{"tag":"strong","children":["Validate"]},", then ",{"tag":"strong","children":["Run Simulation"]},". Loading the demo supplies example settings. You should see a network, a validation report, and simulation results. Warnings deserve attention but do not necessarily mean the model is invalid."]},{"tag":"p","children":["After this check, click ",{"tag":"strong","children":["New blank"]}," to begin the tutorial. Confirm replacement when prompted."]},{"tag":"h3","children":["0E. Build the portable app using GitHub online"]},{"tag":"p","children":["For maintainers with workflow permissions, the repository now has ",{"tag":"strong","children":["Actions → Windows portable release"]},". Select ",{"tag":"strong","children":["Run workflow"]}," and wait for the run to finish successfully. Open the run and download the ",{"tag":"code","children":["windows-portable-<source SHA>"]}," artifact, which contains the application ZIP and checksum. Extract the downloaded artifact container, then extract ",{"tag":"code","children":["GERT-Studio-Windows.zip"]}," before launching the EXE."]},{"tag":"p","children":["A manual run checks out ",{"tag":"strong","children":["main"]},", even if another workflow ref is selected. It creates a downloadable build artifact; it does not automatically publish a new Release. The workflow also runs when a GitHub Release is published and attaches built outputs to that Release. It does not run on every push. Release-triggered source must belong to main. Building successfully is not the same as passing clean-machine acceptance; read the run summary and verification requirements."]},{"tag":"p","children":["Ordinary users should download the existing release asset in 0A and do not need to build anything."]}]},
  {"id":"lesson-4","title":"1. Understand the building blocks","content":[{"tag":"h2","children":["1. Understand the building blocks"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Concept"]},{"tag":"th","children":["Meaning"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Start node"]},{"tag":"td","children":["The one node holding initial inventory at time zero"]}]},{"tag":"tr","children":[{"tag":"td","children":["State node"]},{"tag":"td","children":["A place where produced items accumulate and enable further work"]}]},{"tag":"tr","children":[{"tag":"td","children":["Terminal node"]},{"tag":"td","children":["A modeled project outcome that ends the realization when reached"]}]},{"tag":"tr","children":[{"tag":"td","children":["Item"]},{"tag":"td","children":["A named, quantified consumable flow input or output"]}]},{"tag":"tr","children":[{"tag":"td","children":["Activity"]},{"tag":"td","children":["Consumes required items at one source and takes time"]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome"]},{"tag":"td","children":["One alternative selected when an activity completes; produces items at its target"]}]},{"tag":"tr","children":[{"tag":"td","children":["Realization"]},{"tag":"td","children":["One simulated execution of the entire network"]}]}]}]},{"tag":"p","children":["Activities appear as connections with outcome branches. A multi-outcome activity is one activity, not several competing activities."]},{"tag":"p","children":["There is no single token that must occupy one node. Different activities can execute simultaneously. Items are consumed at activity start and outputs arrive at completion. They are not reusable machine or staffing capacity."]},{"tag":"p","children":[{"tag":"strong","children":["Two rules shape our example:"]}," Start cannot receive incoming outcomes, and reaching a Terminal ends the whole realization. We therefore start with ",{"tag":"strong","children":["one component per realization"]},". Later we study multiple components separately."]},{"tag":"h3","children":["1.1 What “consumable” means"]},{"tag":"p","children":["A consumable item is a ",{"tag":"strong","children":["quantity available for an activity to use"]},". It can represent physical material, a component, a work request, or evidence that a prerequisite has been satisfied. “Consumed” means removed from the source node's inventory when an activity starts; it does not necessarily mean physically destroyed."]},{"tag":"p","children":["For example, Inspection consumes one ",{"tag":"code","children":["component"]}," at Uninspected component. That component is now being inspected, so another activity cannot use the same inventory unit. On completion, the selected outcome produces a component at Accepted or Rework ready. The model represents the item's movement or change of state through explicit consumption and production."]},{"tag":"p","children":["Think of each node as a local inventory and each activity as a recipe: ",{"tag":"strong","children":["what must be available, how much is used, how long the work takes, and what one selected outcome produces"]},"."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Modeling purpose"]},{"tag":"th","children":["Example requirements per instance"]},{"tag":"th","children":["Example production"]},{"tag":"th","children":["What it expresses"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Move a component"]},{"tag":"td","children":["component: 1"]},{"tag":"td","children":["component: 1 at a later node"]},{"tag":"td","children":["Work transforms or transfers its state"]}]},{"tag":"tr","children":[{"tag":"td","children":["Use raw material"]},{"tag":"td","children":["steel_kg: 2.5"]},{"tag":"td","children":["part: 1"]},{"tag":"td","children":["A recipe converts measured material into a part"]}]},{"tag":"tr","children":[{"tag":"td","children":["Consume a test sample"]},{"tag":"td","children":["sample: 1"]},{"tag":"td","children":["test_report: 1"]},{"tag":"td","children":["A destructive test leaves a report rather than returning the sample"]}]},{"tag":"tr","children":[{"tag":"td","children":["Trigger a work package"]},{"tag":"td","children":["design_request: 1"]},{"tag":"td","children":["drawing_package: 1"]},{"tag":"td","children":["A request permits one execution"]}]},{"tag":"tr","children":[{"tag":"td","children":["Synchronize prerequisites"]},{"tag":"td","children":["mechanical_module: 1 AND software_build: 1"]},{"tag":"td","children":["prototype: 1"]},{"tag":"td","children":["Both outputs must have arrived at one source"]}]},{"tag":"tr","children":[{"tag":"td","children":["Route a choice"]},{"tag":"td","children":["choice_token: 1"]},{"tag":"td","children":["route_a_request: 1 OR route_b_request: 1"]},{"tag":"td","children":["One selected probabilistic outcome enables one route"]}]},{"tag":"tr","children":[{"tag":"td","children":["Request rework"]},{"tag":"td","children":["repair_request: 1"]},{"tag":"td","children":["component: 1 at inspection buffer"]},{"tag":"td","children":["Repair enables another inspection"]}]}]}]},{"tag":"p","children":["A single outcome can produce several item types at its single target. For instance, Build may produce ",{"tag":"code","children":["prototype: 1"]}," and ",{"tag":"code","children":["test_request: 1"]}," at Test ready; Test consumes both. Distinct outcomes are alternatives: producing one item in each of two outcomes does ",{"tag":"strong","children":["not"]}," produce both together."]},{"tag":"h3","children":["1.2 Quantities determine how much work can start"]},{"tag":"p","children":["Suppose a source holds Component ",{"tag":"code","children":["5"]},", and Inspection requires Component ",{"tag":"code","children":["2"]}," per instance. Two instances start together, consuming ",{"tag":"code","children":["4"]},"; Component ",{"tag":"code","children":["1"]}," remains. A third cannot start until enough additional inventory arrives. GERT does not automatically queue the five components through a single inspector."]},{"tag":"p","children":["With multiple requirements, the scarcest input determines the maximum count. If Assembly requires Bolt ",{"tag":"code","children":["2"]}," and Plate ",{"tag":"code","children":["1"]},", and its source contains Bolt ",{"tag":"code","children":["7"]}," and Plate ",{"tag":"code","children":["2"]},", it can start ",{"tag":"code","children":["min(floor(7/2), floor(2/1)) = 2"]}," instances. It consumes Bolt ",{"tag":"code","children":["4"]}," and Plate ",{"tag":"code","children":["2"]},", leaving Bolt ",{"tag":"code","children":["3"]}," and Plate ",{"tag":"code","children":["0"]},"."]},{"tag":"p","children":["This calculation describes one activity in isolation. With several enabled activities sharing inventory, GERT checks their combined maximum demand. It reports resource competition ambiguity when that demand cannot be satisfied; it does not select an allocation automatically."]},{"tag":"h3","children":["1.3 Items can represent logical prerequisites"]},{"tag":"p","children":["An ",{"tag":"code","children":["approval_document"]}," can mean “approval is available to authorize this next step.” Consuming it permits one execution. If two independent downstream tasks should both follow approval, explicitly design a handoff activity that consumes approval and produces two distinct request items at a shared node. Each task consumes its own request. Making both tasks require the same one approval item would create competition."]},{"tag":"p","children":["Similarly, a request token can prevent uncontrolled repetition. A zero-duration routing activity still requires a positive consumable input. If each execution consumes one request and nothing recreates it, it cannot execute endlessly without new input. A loop that recreates its request can repeat, so finite simulation limits remain important."]},{"tag":"h3","children":["1.4 Inventory is local, and units are your responsibility"]},{"tag":"p","children":["If Integration needs one mechanical module and one software build, those items must be at Integration's source node. A module at node A and a build at node B cannot be consumed together merely because both appear in the graph."]},{"tag":"p","children":["Quantities can be fractional and use exact decimal comparisons. With Steel ",{"tag":"code","children":["5.0"]}," kg and a requirement of ",{"tag":"code","children":["2.5"]}," kg, two instances are possible. With ",{"tag":"code","children":["4.999"]}," kg, only one is possible. The engine does not round the shortage away."]},{"tag":"p","children":["Declare item types with clear units, such as ",{"tag":"code","children":["steel_kg"]},", and keep quantities consistent. Unit conversion is not automatic. Inventory and production are numbers in the model, not physical conservation laws enforced by the engine: you must justify your recipes, yields, losses, and any production of multiple outputs."]},{"tag":"h3","children":["1.5 Flow items versus reusable capacity"]},{"tag":"p","children":["A machine, engineer, or laboratory slot is normally a reusable capacity resource: reserved while work runs, then released. The current flow model uses consumable items. Declaring Machine ",{"tag":"code","children":["1"]}," as an input consumes it; the application does not automatically reserve and return a machine or schedule a capacity queue."]},{"tag":"p","children":["Returning a token through an outcome can represent an explicit flow protocol in some models, but it does not add built-in staffing, calendars, priorities, queues, or machine scheduling. Document that assumption carefully and inspect competition. For the tutorial, use components, requests, and produced deliverables as items."]},{"tag":"p","children":[{"tag":"strong","children":["Exercises:"]}," (a) Given Bolt ",{"tag":"code","children":["9"]}," and Plate ",{"tag":"code","children":["3"]},", with requirements Bolt ",{"tag":"code","children":["2"]}," and Plate ",{"tag":"code","children":["1"]},", predict the maximum starts and leftovers. Answer: 3 starts; Bolt ",{"tag":"code","children":["3"]},", Plate ",{"tag":"code","children":["0"]},". (b) Give two activities the same single request and explain why they compete. (c) Redesign that request as a routing choice or two independent requests according to what the process actually means."]}]},
  {"id":"lesson-5","title":"2. Build the first inspection network","content":[{"tag":"h2","children":["2. Build the first inspection network"]},{"tag":"h3","children":["2.1 Name the project and create an item"]},{"tag":"p","children":["In ",{"tag":"strong","children":["Model"]},", enter Project name ",{"tag":"code","children":["Quality-control tutorial"]},". Expand ",{"tag":"strong","children":["Project identity"]}," and set Project ID ",{"tag":"code","children":["qc-tutorial"]},"."]},{"tag":"p","children":["Click ",{"tag":"strong","children":["+ Item"]},". In Properties enter:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Field"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Item ID"]},{"tag":"td","children":[{"tag":"code","children":["component"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Item label"]},{"tag":"td","children":[{"tag":"code","children":["Component"]}]}]}]}]},{"tag":"p","children":["An ID is a stable reference. A label is the readable name displayed in the editor."]},{"tag":"h3","children":["2.2 Create the nodes"]},{"tag":"p","children":["Use ",{"tag":"strong","children":["+ Start"]},", ",{"tag":"strong","children":["+ State"]},", and ",{"tag":"strong","children":["+ Terminal"]}," to create these nodes; select each to fill Properties:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Node type"]},{"tag":"th","children":["Node ID"]},{"tag":"th","children":["Node label"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Start"]},{"tag":"td","children":[{"tag":"code","children":["start"]}]},{"tag":"td","children":["Project start"]}]},{"tag":"tr","children":[{"tag":"td","children":["State"]},{"tag":"td","children":[{"tag":"code","children":["ready"]}]},{"tag":"td","children":["Uninspected component"]}]},{"tag":"tr","children":[{"tag":"td","children":["Terminal"]},{"tag":"td","children":[{"tag":"code","children":["accepted"]}]},{"tag":"td","children":["Accepted"]}]}]}]},{"tag":"p","children":["For Start, click ",{"tag":"strong","children":["+ Add initial inventory item"]},", choose Component, and enter Quantity ",{"tag":"code","children":["1"]},"."]},{"tag":"p","children":["For Accepted, enter Outcome code ",{"tag":"code","children":["accepted"]},", Outcome label ",{"tag":"code","children":["Component accepted"]},", and Outcome category ",{"tag":"code","children":["success"]},"."]},{"tag":"p","children":["State nodes begin empty. Their items arrive through activity outputs."]},{"tag":"h3","children":["2.3 Add the preparation activity"]},{"tag":"p","children":["Connect the Start node's output handle to the Uninspected component node's input handle. Alternatively, click ",{"tag":"strong","children":["+ Activity"]}," and choose its Source node and outcome Target node in Properties."]},{"tag":"p","children":["Enter:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Field"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Activity ID / label"]},{"tag":"td","children":[{"tag":"code","children":["prepare"]}," / Prepare inspection"]}]},{"tag":"tr","children":[{"tag":"td","children":["Source node"]},{"tag":"td","children":["Project start"]}]},{"tag":"tr","children":[{"tag":"td","children":["Requirements"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Distribution / value"]},{"tag":"td","children":["Fixed / ",{"tag":"code","children":["0"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome ID / Branch label"]},{"tag":"td","children":[{"tag":"code","children":["ready"]}," / Ready"]}]},{"tag":"tr","children":[{"tag":"td","children":["Probability"]},{"tag":"td","children":[{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Target node"]},{"tag":"td","children":["Uninspected component"]}]},{"tag":"tr","children":[{"tag":"td","children":["Produced items"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]}]}]},{"tag":"p","children":["Use the ",{"tag":"strong","children":["+ Add requirements item"]}," and ",{"tag":"strong","children":["+ Add produced items item"]}," buttons to add quantities. Zero duration means immediate preparation; it still consumes a positive input. This State buffer will also receive future rework outputs."]},{"tag":"h3","children":["2.4 Add Inspection"]},{"tag":"p","children":["Connect Uninspected component to Accepted and fill:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Field"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Activity ID / label"]},{"tag":"td","children":[{"tag":"code","children":["inspection"]}," / Inspection"]}]},{"tag":"tr","children":[{"tag":"td","children":["Source node"]},{"tag":"td","children":["Uninspected component"]}]},{"tag":"tr","children":[{"tag":"td","children":["Requirements"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Distribution / value"]},{"tag":"td","children":["Fixed / ",{"tag":"code","children":["2"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome ID / Branch label"]},{"tag":"td","children":[{"tag":"code","children":["pass"]}," / Pass"]}]},{"tag":"tr","children":[{"tag":"td","children":["Probability"]},{"tag":"td","children":[{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Target node"]},{"tag":"td","children":["Accepted"]}]},{"tag":"tr","children":[{"tag":"td","children":["Produced items"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]}]}]},{"tag":"p","children":["Drag the elements into a readable arrangement and use ",{"tag":"strong","children":["Fit View"]}," if needed."]},{"tag":"p","children":["Click ",{"tag":"strong","children":["Validate"]},". Fix any errors before continuing. At this point there is exactly one Start, each activity consumes a positive quantity, and every activity's probabilities sum to one."]}]},
  {"id":"lesson-6","title":"3. Run and check your first simulation","content":[{"tag":"h2","children":["3. Run and check your first simulation"]},{"tag":"p","children":["In ",{"tag":"strong","children":["Simulation settings"]},", enter every required field:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Setting"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Realizations"]},{"tag":"td","children":[{"tag":"code","children":["1000"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Seed (optional)"]},{"tag":"td","children":[{"tag":"code","children":["20260930"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Max simulation time"]},{"tag":"td","children":[{"tag":"code","children":["100"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Max activity instances"]},{"tag":"td","children":[{"tag":"code","children":["1000"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Max activity completions"]},{"tag":"td","children":[{"tag":"code","children":["1000"]}]}]}]}]},{"tag":"p","children":["Limits apply per realization. These values are tutorial choices, not defaults or recommended settings for every project."]},{"tag":"p","children":["Click ",{"tag":"strong","children":["Run Simulation"]},". Every realization starts from the same initial inventory. For this deterministic model, the expected result is:"]},{"tag":"ul","children":[{"tag":"li","children":["Accepted count: 1000; probability: 1."]},{"tag":"li","children":["Completion time mean, median, and observed minimum/maximum: 2 hours."]},{"tag":"li","children":["Mean starts for Prepare inspection and Inspection: 1 each."]},{"tag":"li","children":["No deadlocks, ambiguities, or cutoffs."]}]},{"tag":"p","children":["Time is preparation ",{"tag":"code","children":["0"]}," plus inspection ",{"tag":"code","children":["2"]},". A realization is a whole project execution; 1000 realizations does not place 1000 components in one network execution."]},{"tag":"h3","children":["3.1 Match the names to their meaning"]},{"tag":"p","children":["The current editor uses ",{"tag":"strong","children":["Realizations"]},", not “resolutions.” Each realization is one complete simulated project execution. “Max processes” is not a current field label: the two activity-count limits below count starts and completions, not operating-system processes or the number of activities allowed to run simultaneously."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Visible setting"]},{"tag":"th","children":["Meaning"]},{"tag":"th","children":["Scope and valid input"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Realizations"]},{"tag":"td","children":["How many independent project executions to simulate"]},{"tag":"td","children":["Whole experiment; positive integer"]}]},{"tag":"tr","children":[{"tag":"td","children":["Seed (optional)"]},{"tag":"td","children":["Identifies the repeatable random sequence"]},{"tag":"td","children":["Whole experiment; integer, or blank for a generated seed"]}]},{"tag":"tr","children":[{"tag":"td","children":["Max simulation time"]},{"tag":"td","children":["Furthest permitted simulation timestamp"]},{"tag":"td","children":["Each realization; finite nonnegative number in your chosen time unit"]}]},{"tag":"tr","children":[{"tag":"td","children":["Max activity instances"]},{"tag":"td","children":["Maximum total activity executions that may start"]},{"tag":"td","children":["Each realization, across all activities and repetitions; nonnegative integer"]}]},{"tag":"tr","children":[{"tag":"td","children":["Max activity completions"]},{"tag":"td","children":["Maximum total executions whose completion events may be processed"]},{"tag":"td","children":["Each realization, across all activities and repetitions; nonnegative integer"]}]}]}]},{"tag":"p","children":["All three limits are required in a blank project. Zero is an explicit value, not “unlimited.” None of these fields sets a concurrency cap or selects how many CPU workers to use. They also do not impose a wall-clock timeout on your computer."]},{"tag":"h3","children":["3.2 Realizations: repeat the project, do not add inventory"]},{"tag":"p","children":["Realizations ",{"tag":"code","children":["1000"]}," with Start Component ",{"tag":"code","children":["1"]}," simulates 1000 separate one-component projects. Start Component ",{"tag":"code","children":["1000"]}," with Realizations ",{"tag":"code","children":["1"]}," models one project with 1000 components, whose activity instances may overlap. These have different terminal and concurrency behavior."]},{"tag":"p","children":["For an 80% pass probability without rework, 100 realizations have an expected 80 passes but can produce a different count; 1000 have an expected 800, again with sampling variation. Neither setting forces an exact 80/20 split."]},{"tag":"p","children":["For independent Bernoulli outcomes, approximate standard error of an estimated probability is ",{"tag":"code","children":["sqrt(p(1-p)/N)"]},". At p = 0.80:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Realizations N"]},{"tag":"th","children":["Approximate standard error"]},{"tag":"th","children":["Approximate normal 95% margin"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["100"]},{"tag":"td","children":["0.040 = 4 percentage points"]},{"tag":"td","children":["±7.8 percentage points"]}]},{"tag":"tr","children":[{"tag":"td","children":["1000"]},{"tag":"td","children":["0.0126 = 1.26 percentage points"]},{"tag":"td","children":["±2.5 percentage points"]}]},{"tag":"tr","children":[{"tag":"td","children":["10000"]},{"tag":"td","children":["0.004 = 0.4 percentage points"]},{"tag":"td","children":["±0.78 percentage points"]}]}]}]},{"tag":"p","children":["These normal-approximation teaching calculations are not guaranteed bounds. The current app reports ",{"tag":"strong","children":["Wilson"]}," probability intervals instead; see Lesson 8. Do not expect its displayed endpoints to match this symmetric approximation exactly. Rare outcomes need special care: a true event probability of 0.001 yields only one expected observation in 1000 trials; seeing zero does not prove impossibility. Completion-time quantiles have their own sampling uncertainty."]},{"tag":"p","children":["Four times as many realizations roughly halves this standard error. It can also multiply computational work. First verify the model with a small run, then increase N for the estimates you need. More realizations cannot repair incorrect assumptions or an overly restrictive horizon."]},{"tag":"h3","children":["3.3 Seed: repeat a random experiment"]},{"tag":"p","children":["Enter Seed ",{"tag":"code","children":["20260930"]},", run, and rerun with identical model, settings, engine, and reproducibility version. The numerical results should repeat within that implementation's reproducibility guarantees. A different seed yields another sample, not a different mathematical model. An empty seed generates one; retain Actual seed from the results to replay it."]},{"tag":"p","children":["Use a fixed seed when checking edits or reproducing a problem. Exploring several seeds can reveal sampling variability. Keep version and platform information as explained in Lesson 9. The seed is not a confidence level, trial count, or limit."]},{"tag":"h3","children":["3.4 Max simulation time: a model-time horizon"]},{"tag":"p","children":["If durations are in hours, a horizon of ",{"tag":"code","children":["100"]}," means 100 simulated hours, regardless of how long the computer takes. It does not run the computer for 100 hours, multiply durations, or truncate a 12-hour activity into a shorter activity."]},{"tag":"p","children":["Example: one activity starts at time 0 with Fixed ",{"tag":"code","children":["12"]},". With horizon ",{"tag":"code","children":["10"]},", its completion cannot be processed, so the realization ends at Time cutoff with that instance unfinished. At horizon ",{"tag":"code","children":["12"]},", completion is permitted. A cutoff is not a modeled rejection and is excluded from terminal completion-time statistics."]},{"tag":"p","children":["In the tutorial, Prepare takes 0 hours and Inspection takes 2. Horizon ",{"tag":"code","children":["1"]}," causes a time cutoff; horizon ",{"tag":"code","children":["2"]}," permits the deterministic terminal. In the rework lesson, horizon ",{"tag":"code","children":["7"]}," allows first-pass completion at 2 or completion after one repair at exactly 7. It leaves theoretical cutoff probability 0.04."]},{"tag":"p","children":["A zero horizon still permits finite zero-duration work at timestamp 0, subject to the count limits. A zero-duration cycle therefore needs activity-count safeguards; increasing the time horizon cannot bound a loop that never advances time."]},{"tag":"h3","children":["3.5 Max activity instances: count starts, including repeats"]},{"tag":"p","children":["An activity ",{"tag":"strong","children":["definition"]}," is the recipe drawn in the graph. An ",{"tag":"strong","children":["instance"]}," is one execution. Inspection executed 20 times counts as 20 instances even though there is only one Inspection definition. The cap counts all starts in one realization, including Preparation, routing, rework, and parallel work."]},{"tag":"p","children":["The deterministic tutorial needs two starts: Prepare and Inspection. Max activity instances ",{"tag":"code","children":["1"]}," allows Prepare but blocks Inspection's start. A cap of ",{"tag":"code","children":["2"]}," permits both, provided the other limits also permit their completions."]},{"tag":"p","children":["For a conflict-free launch group of three instances, a remaining start budget of two does not admit two and leave the third behind. The whole launch group is blocked and the realization gets Instance-count cutoff. This preserves the model's concurrency semantics. Resource competition, if genuinely observed, is handled as ambiguity rather than solved by the cap."]},{"tag":"p","children":[{"tag":"strong","children":["Do not use this cap as “maximum parallel processes.”"]}," If three inputs enable three simultaneous inspections but the cap is one, GERT does not inspect them serially. A serial-capacity policy would need explicit modeling support."]},{"tag":"h3","children":["3.6 Max activity completions: count processed finishes"]},{"tag":"p","children":["Started work need not complete before a run ends. This separate budget limits completed instances. In the deterministic tutorial, completion cap ",{"tag":"code","children":["1"]}," permits Prepare's completion but blocks Inspection's completion, even if Inspection was allowed to start. Cap ",{"tag":"code","children":["2"]}," permits both and their terminal result."]},{"tag":"p","children":["Simultaneous finishes form an atomic batch. If three inspections finish at the same timestamp and only two completions remain in the budget, none of those three completion outcomes is processed; the run receives Completion-count cutoff. The engine does not process two to discover whether one is terminal."]},{"tag":"p","children":["If a permitted completion batch reaches a Terminal exactly at the count limit, the terminal result takes precedence over merely reaching that limit. When a prospective completion exceeds both the time horizon and the completion budget, the time cutoff is checked first. These rules prevent partial or ordering-dependent results."]},{"tag":"h3","children":["3.7 Count a loop before choosing its limits"]},{"tag":"p","children":["In our fixed-duration rework model, let K be the number of failed inspections before success:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Path"]},{"tag":"th","children":["Completion time"]},{"tag":"th","children":["Total starts and completions if terminal is reached"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Immediate pass, K = 0"]},{"tag":"td","children":["2"]},{"tag":"td","children":["Prepare 1 + Inspection 1 = 2"]}]},{"tag":"tr","children":[{"tag":"td","children":["One fail then pass, K = 1"]},{"tag":"td","children":["7"]},{"tag":"td","children":["Prepare 1 + Inspection 2 + Rework 1 = 4"]}]},{"tag":"tr","children":[{"tag":"td","children":["Two fails then pass, K = 2"]},{"tag":"td","children":["12"]},{"tag":"td","children":["Prepare 1 + Inspection 3 + Rework 2 = 6"]}]},{"tag":"tr","children":[{"tag":"td","children":["K failures then pass"]},{"tag":"td","children":["2 + 5K"]},{"tag":"td","children":["2 + 2K"]}]}]}]},{"tag":"p","children":["With both count caps ",{"tag":"code","children":["4"]}," and horizon ",{"tag":"code","children":["100"]},", paths that pass after at most one failure can reach a terminal. If the second inspection fails, its allowed completion leaves a repair request, but a fifth start is blocked. Some run statuses therefore become Instance-count cutoff rather than Time cutoff. This illustrates why changing the limits can change outcome estimates even when all probabilities are unchanged."]},{"tag":"h3","children":["3.8 Choose limits deliberately and record them"]},{"tag":"p","children":["For an initial check, use a modest realization count and limits high enough to admit known ordinary paths. Inspect all cutoff statuses and unfinished work. Then increase one restrictive limit at a time and compare terminal probabilities, sample sizes, and conditional times using the same seed and model."]},{"tag":"p","children":["A horizon may represent a genuine research question: “What fraction finish within 30 days?” In that case, keep it and describe results as finite-horizon observations. If it is merely a safety guard, test that increasing it does not materially change the conclusions. Finite simulations cannot prove a loop will never terminate."]},{"tag":"p","children":["The guide's ",{"tag":"code","children":["1000 / 100 / 1000 / 1000"]}," choices are examples, not universal defaults. Settings are separate from a model-only export; a current-result snapshot now includes the actual used settings, seed, and versions. Keep that snapshot when sharing results."]},{"tag":"p","children":[{"tag":"strong","children":["Parameter exercise:"]}," on the deterministic tutorial, change only one field per run. Horizon ",{"tag":"code","children":["1"]}," → Time cutoff; instance cap ",{"tag":"code","children":["1"]}," → Instance-count cutoff; completion cap ",{"tag":"code","children":["1"]}," → Completion-count cutoff. Restore generous limits between experiments, then confirm time ",{"tag":"code","children":["2"]}," with both count caps ",{"tag":"code","children":["2"]}," and horizon ",{"tag":"code","children":["2"]},"."]}]},
  {"id":"lesson-7","title":"4. Save models, drafts, and simulation results","content":[{"tag":"h2","children":["4. Save models, drafts, and simulation results"]},{"tag":"p","children":[{"tag":"strong","children":["Export JSON"]}," now has two behaviors:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Editor state when you export"]},{"tag":"th","children":["File contents"]},{"tag":"th","children":["What importing restores"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["No current simulation results"]},{"tag":"td","children":["Model-only JSON, including documentation and valid draft nulls"]},{"tag":"td","children":["Network; settings are not loaded from a model-only file"]}]},{"tag":"tr","children":[{"tag":"td","children":["Current simulation results exist"]},{"tag":"td","children":["Versioned simulation snapshot: model + used settings + actual seed + engine/reproducibility versions + full report"]},{"tag":"td","children":["Network, saved settings, and saved results without rerunning"]}]}]}]},{"tag":"p","children":["Export immediately after the deterministic run in Lesson 3 and save the download as ",{"tag":"code","children":["qc-01-deterministic-results.json"]},". It is now a ",{"tag":"strong","children":["snapshot"]},", not just a model. At the top level it has ",{"tag":"code","children":["file_type: \"gert-studio-simulation-snapshot\""]},", ",{"tag":"code","children":["file_version: \"0.1\""]},", ",{"tag":"code","children":["model"]},", ",{"tag":"code","children":["simulation_settings"]},", and ",{"tag":"code","children":["simulation_result"]},". Keep it intact rather than editing report totals manually."]},{"tag":"p","children":["To save a model-only file, export at a point when no results are currently retained, such as before running. The button automatically uses the current editor state; it does not offer a separate model-only toggle. In the inspected implementation, ",{"tag":"strong","children":["Validate"]}," also clears currently displayed results before validation; export a snapshot first if you want to preserve them."]},{"tag":"h3","children":["Reopen a snapshot"]},{"tag":"ol","children":[{"tag":"li","children":["Export the current workspace before replacing it."]},{"tag":"li","children":["Click ",{"tag":"strong","children":["Import JSON"]},", choose your saved snapshot, and confirm replacement when prompted."]},{"tag":"li","children":["The application validates the embedded model and checks snapshot structure and consistency."]},{"tag":"li","children":["Results display ",{"tag":"strong","children":["Imported saved results · No simulation was rerun."]}," The saved settings are restored."]},{"tag":"li","children":["Review Actual seed and versions. Imported results are historical data, not evidence of a new run on the current runtime."]}]},{"tag":"p","children":["To recompute, click ",{"tag":"strong","children":["Run Simulation"]}," using those settings. Preserve the original snapshot if you want to compare. A supported snapshot is consistency-checked, not independently recomputed or cryptographically authenticated on import."]},{"tag":"h3","children":["Reopen a model or incomplete draft"]},{"tag":"p","children":["A model-only import replaces the network without loading simulation settings; check the current fields before running. A structurally valid draft with explicit null duration/probability inputs can now be exported and imported. Validation identifies ",{"tag":"strong","children":["Draft valid · Complete missing inputs before simulation"]},". Invalid supplied values or broken structure still block import. A rejected import leaves the current network unchanged; its diagnostics refer to the rejected file."]},{"tag":"p","children":["This updates the old tutorial's rule that incomplete drafts could not be reopened. See Lesson 16 for exact null examples."]},{"tag":"h3","children":["What is and is not saved automatically"]},{"tag":"p","children":["Model/settings edits clear current results, including restored results. Even a documentation edit clears the displayed report in this editor, although documentation does not change simulation mathematics. Undo also clears results; changing panel sizes does not."]},{"tag":"p","children":["Canvas layout is regenerated on import. ",{"tag":"strong","children":["Panel sizes"]},", unlike graph layout and model data, persist locally. There is still no automatic model/database persistence: export before refreshing, closing, or replacing your work. A result snapshot can be much larger than a model-only file because it retains full per-realization and per-instance data."]},{"tag":"p","children":[{"tag":"strong","children":["Checkpoint:"]}," import ",{"tag":"code","children":["qc-01-deterministic-results.json"]}," and verify the saved-results message, restored settings, and terminal time 2. Then rerun and compare. Export another copy before changing the model."]}]},
  {"id":"lesson-8","title":"5. Add probabilistic pass/fail outcomes","content":[{"tag":"h2","children":["5. Add probabilistic pass/fail outcomes"]},{"tag":"p","children":["Create a second Terminal:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Field"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Node ID / label"]},{"tag":"td","children":[{"tag":"code","children":["rejected"]}," / Rejected"]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome code / label"]},{"tag":"td","children":[{"tag":"code","children":["rejected"]}," / Component rejected"]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome category"]},{"tag":"td","children":[{"tag":"code","children":["failure"]}]}]}]}]},{"tag":"p","children":["Select ",{"tag":"strong","children":["Inspection"]}," and click ",{"tag":"strong","children":["+ Add outcome"]},". Fill the new outcome completely: ID ",{"tag":"code","children":["fail"]},", Branch label ",{"tag":"code","children":["Fail"]},", Target node Rejected, Produced items Component ",{"tag":"code","children":["1"]},"."]},{"tag":"p","children":["Set Pass probability ",{"tag":"code","children":["0.80"]}," and Fail probability ",{"tag":"code","children":["0.20"]},". While adding a branch, values can be incomplete; explicitly fill both and verify ",{"tag":"strong","children":["Probability total: 1"]},". While any probability is unknown, editing one field changes only that field—even when filling the last unknown. After the set is complete and individually valid, subsequent probability edits adjust the others proportionally; a single complete outcome stays at 1. Always validate the completed total. Unknown values are never silently filled."]},{"tag":"p","children":["These probabilities belong to alternatives within Inspection. They do not define whether unrelated activities run."]},{"tag":"p","children":["Validate and simulate. Expect approximately 80% Accepted and 20% Rejected; finite Monte Carlo samples usually differ from those exact fractions. Completion time remains 2 hours because both outcomes follow the same fixed-duration inspection."]},{"tag":"p","children":["Export as ",{"tag":"code","children":["qc-02-pass-fail.json"]},". Because this follows a simulation, the file includes a result snapshot."]}]},
  {"id":"lesson-9","title":"6. Explore uncertain durations","content":[{"tag":"h2","children":["6. Explore uncertain durations"]},{"tag":"p","children":["Select Inspection and change ",{"tag":"strong","children":["Distribution"]},". Changing distribution clears its parameters: fill every field explicitly."]},{"tag":"p","children":["Try one row at a time, validating and running after each change:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Distribution"]},{"tag":"th","children":["Values"]},{"tag":"th","children":["Meaning"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Fixed"]},{"tag":"td","children":["value ",{"tag":"code","children":["2"]}]},{"tag":"td","children":["Always 2 hours"]}]},{"tag":"tr","children":[{"tag":"td","children":["Uniform"]},{"tag":"td","children":["min ",{"tag":"code","children":["1"]},", max ",{"tag":"code","children":["3"]}]},{"tag":"td","children":["Constant density between 1 and 3"]}]},{"tag":"tr","children":[{"tag":"td","children":["Triangular"]},{"tag":"td","children":["min ",{"tag":"code","children":["1"]},", mode ",{"tag":"code","children":["2"]},", max ",{"tag":"code","children":["4"]}]},{"tag":"td","children":["Density peaks at 2 within the bounds"]}]},{"tag":"tr","children":[{"tag":"td","children":["Beta-PERT"]},{"tag":"td","children":["min ",{"tag":"code","children":["1"]},", mode ",{"tag":"code","children":["2"]},", max ",{"tag":"code","children":["4"]},", lambda ",{"tag":"code","children":["4"]}]},{"tag":"td","children":["Bounded beta distribution using the explicit shape parameter"]}]}]}]},{"tag":"p","children":["All values must be finite and nonnegative; min ≤ mode ≤ max where applicable. Beta-PERT also requires lambda > 0. The ",{"tag":"code","children":["4"]}," shown here is an example you enter, not a default."]},{"tag":"p","children":["For this Beta-PERT choice, the theoretical mean inspection duration is ",{"tag":"code","children":["(1 + 4×2 + 4)/(4+2) = 13/6"]},", approximately 2.167 hours. Compare the simulation's mean to that benchmark. Sample means vary."]},{"tag":"p","children":["Uncertain duration and uncertain outcome are separate: a single outcome can still have a random duration. Use Fixed ",{"tag":"code","children":["2"]}," again for the next lesson so the rework timing is easy to verify."]}]},
  {"id":"lesson-10","title":"7. Add the quality-control rework loop","content":[{"tag":"h2","children":["7. Add the quality-control rework loop"]},{"tag":"p","children":["We now repair rejected components instead of immediately ending their realizations."]},{"tag":"ol","children":[{"tag":"li","children":["Add a ",{"tag":"strong","children":["State"]}," node with ID ",{"tag":"code","children":["rework-ready"]}," and label ",{"tag":"code","children":["Rework ready"]},"."]},{"tag":"li","children":["Change Inspection's Fail target from Rejected to Rework ready. Keep Fail probability ",{"tag":"code","children":["0.20"]}," and produced Component ",{"tag":"code","children":["1"]},"."]},{"tag":"li","children":["Delete the now-unused Rejected Terminal after retargeting the outcome."]},{"tag":"li","children":["Create Rework from Rework ready to Uninspected component."]}]},{"tag":"p","children":["Fill Rework:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Field"]},{"tag":"th","children":["Value"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Activity ID / label"]},{"tag":"td","children":[{"tag":"code","children":["rework"]}," / Rework"]}]},{"tag":"tr","children":[{"tag":"td","children":["Source node"]},{"tag":"td","children":["Rework ready"]}]},{"tag":"tr","children":[{"tag":"td","children":["Requirements"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Distribution / value"]},{"tag":"td","children":["Fixed / ",{"tag":"code","children":["3"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Outcome ID / Branch label"]},{"tag":"td","children":[{"tag":"code","children":["repaired"]}," / Repaired"]}]},{"tag":"tr","children":[{"tag":"td","children":["Probability"]},{"tag":"td","children":[{"tag":"code","children":["1"]}]}]},{"tag":"tr","children":[{"tag":"td","children":["Target node"]},{"tag":"td","children":["Uninspected component"]}]},{"tag":"tr","children":[{"tag":"td","children":["Produced items"]},{"tag":"td","children":["Component: ",{"tag":"code","children":["1"]}]}]}]}]},{"tag":"p","children":["Keep Inspection at Fixed ",{"tag":"code","children":["2"]},". The loop returns to ",{"tag":"code","children":["ready"]},", never to Start."]},{"tag":"pre","children":[{"tag":"code","children":["flowchart TD\n    S[\"Project start\"] -->|\"Prepare: 0 h\"| R[\"Uninspected component\"]\n    R --> I[\"Inspection: 2 h\"]\n    I -->|\"Pass: 0.80\"| A[\"Accepted terminal\"]\n    I -->|\"Fail: 0.20\"| W[\"Rework ready\"]\n    W -->|\"Rework: 3 h\"| R\n"]}]},{"tag":"p","children":["The Inspection box represents one activity with two outcomes. Rework is another activity. Validate, run, and export as ",{"tag":"code","children":["qc-03-rework.json"]},"."]},{"tag":"h3","children":["Predict before simulating"]},{"tag":"p","children":["Let K be the number of failed inspections before acceptance. With independent, unchanged 80% pass probability:"]},{"tag":"ul","children":[{"tag":"li","children":[{"tag":"code","children":["P(K=k) = 0.8 × 0.2^k"]},", for k = 0, 1, 2, …"]},{"tag":"li","children":["Inspection starts = K + 1."]},{"tag":"li","children":["Rework starts = K."]},{"tag":"li","children":["Completion time T = 2 + 5K hours."]}]},{"tag":"p","children":["Without finite cutoffs, eventual acceptance has probability 1, expected inspection starts are 1.25, expected rework starts are 0.25, and mean completion time is 3.25 hours. This does not mean every component passes within any fixed time limit."]},{"tag":"p","children":["With the tutorial's horizon of 100, at most 19 failures followed by a pass complete in time: ",{"tag":"code","children":["2 + 5×19 = 97"]},". The theoretical time-cutoff probability is ",{"tag":"code","children":["0.2^20"]},", so a 1000-realization run will usually observe none. These are mathematical benchmarks, not promised exact sampled counts."]},{"tag":"p","children":["For a visible cutoff experiment, change ",{"tag":"strong","children":["Max simulation time"]}," to ",{"tag":"code","children":["7"]},", keeping the other limits high. A pass on the first attempt completes at 2; one rework then a pass completes at exactly 7 and is permitted. The theoretical probabilities are Accepted ",{"tag":"code","children":["0.96"]}," and Time cutoff ",{"tag":"code","children":["0.04"]},". The mean time among accepted runs is ",{"tag":"code","children":["2.8333…"]},", lower than the unlimited mean because longer paths are omitted."]},{"tag":"p","children":["Restore the horizon to ",{"tag":"code","children":["100"]}," afterward."]}]},
  {"id":"lesson-11","title":"8. Read results correctly","content":[{"tag":"h2","children":["8. Read results correctly"]},{"tag":"h3","children":["Terminal outcomes and run statuses"]},{"tag":"p","children":["Terminal probabilities divide their counts by ",{"tag":"strong","children":["all requested realizations"]},". A failure Terminal is a modeled outcome; a deadlock or cutoff is a separate runtime classification."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Status"]},{"tag":"th","children":["Interpretation"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Reached a terminal"]},{"tag":"td","children":["A modeled terminal ended the realization"]}]},{"tag":"tr","children":[{"tag":"td","children":["Deadlock"]},{"tag":"td","children":["No activities are running and none can start, without reaching a terminal"]}]},{"tag":"tr","children":[{"tag":"td","children":["Resource competition ambiguity"]},{"tag":"td","children":["Enabled activities' combined maximum launch demand exceeds available inputs; the engine does not select a winner"]}]},{"tag":"tr","children":[{"tag":"td","children":["Ambiguous terminals"]},{"tag":"td","children":["Distinct terminals were reached in the same completion batch"]}]},{"tag":"tr","children":[{"tag":"td","children":["Time cutoff"]},{"tag":"td","children":["Further work would exceed the configured time horizon"]}]},{"tag":"tr","children":[{"tag":"td","children":["Completion-count / instance-count cutoff"]},{"tag":"td","children":["The applicable finite activity budget blocks further processing or starts"]}]},{"tag":"tr","children":[{"tag":"td","children":["Invalid runtime state"]},{"tag":"td","children":["Runtime consistency failed; inspect its explanation"]}]}]}]},{"tag":"p","children":["Limits are inclusive. A completion at exactly the time horizon is permitted. Simultaneous completions are processed as a full batch; a batch or launch group exceeding its budget is not partially admitted."]},{"tag":"p","children":["A cutoff does not prove an infinite loop. Increasing a limit may reveal later outcomes."]},{"tag":"h3","children":["Completion-time statistics"]},{"tag":"p","children":["Mean, P5, P10, P20, P30, Median/P50, P70, P80, P90, P95, Min, Max, and descriptive SD are ",{"tag":"strong","children":["conditional on reaching a terminal within the limits"]},". Check the sample size. These statistics pool terminal runs, including both success and failure terminals when both exist. A fast rejection can lower the mean; that does not imply faster successful delivery."]},{"tag":"p","children":["P90 is an estimated 90th percentile of observed terminal completion times. Observed Max is the largest value in this sample, not a guaranteed model bound. The app does not attach generic confidence intervals to observed Min/Max, descriptive SD, or exact lifecycle totals."]},{"tag":"h3","children":["Activity starts and lifecycle"]},{"tag":"p","children":["Mean starts uses all realizations. P(at least one start) measures how often an activity was started. Started and Completed are distinct counts. Running instances cancelled by a terminal differ from instances unfinished when a cutoff, ambiguity, or invalid runtime state ends the run."]},{"tag":"p","children":["For the rework example, Mean starts for Inspection should approach 1.25 and Rework 0.25 with generous limits and many realizations. Finite cutoffs can truncate these counts."]},{"tag":"p","children":["Results show three significant digits by default. For example, 18.34125278 displays as 18.3. Click an individual number to see the returned full value; click again to restore the compact display. This formatting does not change the simulation."]},{"tag":"h3","children":["8.1 Read the expanded statistics and uncertainty controls"]},{"tag":"p","children":["The current completion panel shows ",{"tag":"strong","children":["Mean, SD, P5, P10, P20, P30, Median/P50, P70, P80, P90, P95, Min, and Max"]},". Expand ",{"tag":"strong","children":["Completion-time uncertainty"]}," for inferential sample SD, SE of mean, 95% Student-t CI, and 95% nonparametric quantile CIs. Terminal/status probability rows have ",{"tag":"strong","children":["Uncertainty"]}," details. Activity Mean starts has ",{"tag":"strong","children":["SD & uncertainty"]},"; P(at least one start) has its own probability uncertainty."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Quantity"]},{"tag":"th","children":["What it answers"]},{"tag":"th","children":["Sample used"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Population SD, ddof=0"]},{"tag":"td","children":["How spread out are the observed values?"]},{"tag":"td","children":["Terminal durations, or start counts across all requested realizations"]}]},{"tag":"tr","children":[{"tag":"td","children":["Sample SD, ddof=1"]},{"tag":"td","children":["What spread estimate is used for inference?"]},{"tag":"td","children":["Same relevant sample, requiring at least 2 observations"]}]},{"tag":"tr","children":[{"tag":"td","children":["SE of mean"]},{"tag":"td","children":["How noisy is the estimated mean from finite Monte Carlo sampling?"]},{"tag":"td","children":["Sample SD divided by square root of the relevant sample size"]}]},{"tag":"tr","children":[{"tag":"td","children":["95% Wilson CI"]},{"tag":"td","children":["What interval estimates a terminal/status/start-occurrence probability?"]},{"tag":"td","children":["Success count k and all requested realizations N"]}]},{"tag":"tr","children":[{"tag":"td","children":["95% Student-t CI"]},{"tag":"td","children":["What interval estimates a mean duration or mean starts?"]},{"tag":"td","children":["Sample mean ± t critical value × SE, using n−1 degrees of freedom"]}]},{"tag":"tr","children":[{"tag":"td","children":["95% nonparametric quantile CI"]},{"tag":"td","children":["How uncertain is a percentile estimate?"]},{"tag":"td","children":["Binomial/order-statistic bounds from sorted terminal times"]}]}]}]},{"tag":"p","children":["These intervals describe Monte Carlo estimation uncertainty under the supplied model. They do not quantify whether your probabilities, durations, or process assumptions are correct. “95% confidence” refers to a method's repeated-sampling coverage under its conditions; it is not a 95% probability that the next realization lies inside the interval."]},{"tag":"h3","children":["8.2 Probability example: finite trials and zero observed events"]},{"tag":"p","children":["Suppose 80 of 100 realizations reach Accepted. The estimate is 0.80, probability SE is 0.04, and the displayed 95% Wilson interval is approximately ",{"tag":"strong","children":["0.711 to 0.867"]},". It is not the symmetric 0.80 ± 1.96×0.04 interval used as a simple approximation in Lesson 3."]},{"tag":"p","children":["With zero observed failures in 100 trials, the probability point estimate and plug-in SE are both zero, but Wilson's 95% interval is approximately ",{"tag":"strong","children":["0 to 0.0370"]},". With 100 successes out of 100, it is approximately ",{"tag":"strong","children":["0.963 to 1"]},". Zero-width plug-in SE at the boundary is therefore not proof of a known exact probability."]},{"tag":"p","children":["The same logic applies to P(at least one start): it counts realizations in which the activity starts, not the total number of instances. If Rework starts three times in one realization and zero times in another, that is one success out of two for occurrence probability, and mean starts 1.5."]},{"tag":"h3","children":["8.3 Mean example: spread differs from uncertainty"]},{"tag":"p","children":["For two terminal completion times, 2 and 7 hours:"]},{"tag":"ul","children":[{"tag":"li","children":["Mean = 4.5 hours."]},{"tag":"li","children":["Descriptive population SD = 2.5 hours."]},{"tag":"li","children":["Inferential sample SD = approximately 3.54 hours."]},{"tag":"li","children":["SE of mean = 2.5 hours."]},{"tag":"li","children":["With n−1 = 1 degree of freedom, the Student-t critical value is approximately 12.7, giving a very wide raw interval, about −27.3 to 36.3 hours."]}]},{"tag":"p","children":["The app clips a negative lower endpoint to zero for nonnegative means and labels it ",{"tag":"strong","children":["Support-clipped"]},". The displayed example would therefore be about ",{"tag":"strong","children":["0 to 36.3"]}," hours. Clipping reflects the nonnegative support; it does not supply missing data or make a two-observation mean reliable. Student-t mean inference is exact for independent normal observations and is commonly approximate for nonnormal simulation outputs; heavily skewed loop durations and small samples warrant caution."]},{"tag":"p","children":["More realizations can reduce SE without reducing the process's underlying spread. A narrow mean CI does not mean individual completion times are tightly clustered."]},{"tag":"h3","children":["8.4 Percentiles and small samples"]},{"tag":"p","children":["P5 estimates an early completion threshold; P95 estimates a late threshold. Point estimates use ",{"tag":"strong","children":["Type-7 interpolation"]}," at position ",{"tag":"code","children":["(n−1)×p"]}," in the sorted observations, rather than necessarily selecting one observed time. With observations 2 and 7, P50 is 4.5 even though neither observation is 4.5."]},{"tag":"p","children":["A percentile's CI is a separate, nonparametric rank calculation; it is not mean ± SD, not a Student-t interval, and not a bootstrap. ",{"tag":"strong","children":["Unavailable"]}," quantile endpoints mean there is insufficient sample information for the requested finite two-sided interval. This is especially common for P5/P95 with small samples. Do not replace an unavailable bound with zero, Min, or Max."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Terminal sample size"]},{"tag":"th","children":["Descriptive duration statistics"]},{"tag":"th","children":["Inferential mean statistics"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["0"]},{"tag":"td","children":["Mean, SD, percentiles, Min/Max unavailable"]},{"tag":"td","children":["Sample SD, SE, and mean CI unavailable"]}]},{"tag":"tr","children":[{"tag":"td","children":["1"]},{"tag":"td","children":["Mean and percentile points equal that observation; population SD is 0"]},{"tag":"td","children":["Sample SD, SE, and mean CI unavailable"]}]},{"tag":"tr","children":[{"tag":"td","children":["At least 2"]},{"tag":"td","children":["Available for the observed sample"]},{"tag":"td","children":["Sample SD, SE, and Student-t CI available; adequacy still depends on the data"]}]}]}]},{"tag":"p","children":["Quantile bounds have their own sample-size requirements and may remain unavailable with two or more observations. By contrast, activity-start inference uses ",{"tag":"strong","children":["all requested realizations"]},", including zero-start and nonterminal runs, so its sample size can exceed the duration sample size."]},{"tag":"p","children":["If every observed duration is identical and n≥2, sample SD and SE are zero and the mean CI collapses to the observed mean. That reports the sample behavior under the model; it cannot establish correctness of the model itself."]},{"tag":"p","children":[{"tag":"strong","children":["Exercise:"]}," run the deterministic tutorial with 1 realization. Expect terminal time 2 and population SD 0, but unavailable sample SD/mean SE/mean CI. Repeat with 10 realizations: mean remains 2, both SDs and mean SE are 0, and mean CI is [2,2]. Inspect Wilson uncertainty for the terminal probability as a distinct calculation. Then return to the rework model, compare 100 and 1000 realizations, and check the duration sample size and quantile-bound availability."]}]},
  {"id":"lesson-12","title":"9. Reproduce a simulation","content":[{"tag":"h2","children":["9. Reproduce a simulation"]},{"tag":"p","children":["Record the exported model, every simulation setting, Actual seed, Engine version, and reproducibility version displayed in results."]},{"tag":"p","children":["If Seed is empty, GERT Studio generates and returns one. Copy ",{"tag":"strong","children":["Actual seed"]}," into Seed to repeat the run. The same model, settings, seed, and compatible reproducibility version should repeat the results. Labels and layout are presentation metadata; canonical activity and outcome IDs can affect random draws."]},{"tag":"p","children":["Changing probabilities, durations, inventory, limits, or IDs can change results. Do not compare only screenshots rounded to three significant digits."]},{"tag":"p","children":["The current engine is ",{"tag":"strong","children":["0.1.1"]},", with reproducibility version ",{"tag":"strong","children":[{"tag":"code","children":["gert-v2-py312-sha256-mt19937-crmath1"]}]},". The controlled Beta-PERT numerical implementation is now integrated, addressing the earlier Windows/Linux last-digit divergence. Old seeded Beta-PERT outputs from the previous reproducibility version can change: matching the seed alone is insufficient across versions. Save the engine and reproducibility versions as well."]},{"tag":"p","children":["A result snapshot preserves that metadata and the report, so an old result can be inspected without rerunning. Statistical reporting consumes no simulation RNG draws. See the pinned ",{"tag":"a","children":["reproducibility report"],"href":"https://github.com/gyudar103/gert-studio/blob/52fcd732787d5829d923bf2178594de21704b2dc/docs/REPRODUCIBILITY_REPORT.md"}," for the implementation and recorded verification scope."]}]},
  {"id":"lesson-13","title":"10. Multiple simultaneous instances","content":[{"tag":"h2","children":["10. Multiple simultaneous instances"]},{"tag":"p","children":["Export the rework model before experimenting."]},{"tag":"p","children":["For a simple concurrency experiment, make a separate network with Start Component ",{"tag":"code","children":["3"]},", a State buffer, and one Inspection consuming Component ",{"tag":"code","children":["1"]}," with Fixed ",{"tag":"code","children":["2"]},". Route its sole outcome, probability ",{"tag":"code","children":["1"]},", to a second ",{"tag":"strong","children":["State"]},", producing Component ",{"tag":"code","children":["1"]},". Do not add a Terminal for this experiment."]},{"tag":"p","children":["Preparation transfers all three components through three zero-duration instances. Inspection then launches three instances at time zero and all finish at time 2. Expected counts per realization: three Inspection starts and three completions. Once no work remains, the status is Deadlock because no Terminal was reached; terminal completion-time statistics are unavailable."]},{"tag":"p","children":["This intentionally isolates concurrency. It also explains why a Terminal called Accepted is unsuitable as a bucket for a general 100-component processing model: the first accepted arrival ends the whole realization and can cancel remaining work. All-complete batch logic requires an explicitly designed completion condition."]},{"tag":"p","children":["Do not infer a one-at-a-time inspection machine from a single activity definition. The current engine launches as many instances as its consumable inputs permit; reusable machine capacity scheduling is outside scope."]}]},
  {"id":"lesson-14","title":"11. Parallel activities and synchronization","content":[{"tag":"h2","children":["11. Parallel activities and synchronization"]},{"tag":"p","children":["Create a new project after exporting your current one. Add these item types: ",{"tag":"code","children":["mechanical_request"]},", ",{"tag":"code","children":["software_request"]},", ",{"tag":"code","children":["mechanical_module"]},", ",{"tag":"code","children":["software_build"]},", ",{"tag":"code","children":["prototype"]},"."]},{"tag":"p","children":["Nodes: Start ",{"tag":"code","children":["start"]},", State ",{"tag":"code","children":["integration"]},", Terminal ",{"tag":"code","children":["approved"]}," with unique outcome code ",{"tag":"code","children":["approved"]},", category ",{"tag":"code","children":["success"]},". Start inventory is one mechanical request and one software request."]},{"tag":"p","children":["Each activity below has one outcome with probability ",{"tag":"code","children":["1"]},":"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Activity"]},{"tag":"th","children":["Source"]},{"tag":"th","children":["Requirements"]},{"tag":"th","children":["Fixed duration"]},{"tag":"th","children":["Target"]},{"tag":"th","children":["Produced items"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Mechanical design"]},{"tag":"td","children":["Start"]},{"tag":"td","children":["mechanical_request: 1"]},{"tag":"td","children":["3"]},{"tag":"td","children":["Integration"]},{"tag":"td","children":["mechanical_module: 1"]}]},{"tag":"tr","children":[{"tag":"td","children":["Software build"]},{"tag":"td","children":["Start"]},{"tag":"td","children":["software_request: 1"]},{"tag":"td","children":["5"]},{"tag":"td","children":["Integration"]},{"tag":"td","children":["software_build: 1"]}]},{"tag":"tr","children":[{"tag":"td","children":["Integrate"]},{"tag":"td","children":["Integration"]},{"tag":"td","children":["mechanical_module: 1 AND software_build: 1"]},{"tag":"td","children":["1"]},{"tag":"td","children":["Approved"]},{"tag":"td","children":["prototype: 1"]}]}]}]},{"tag":"p","children":["Both build activities start at time zero because they consume different available inputs. Integration cannot start at time 3: software is still running. It starts at 5 when both items are at the ",{"tag":"strong","children":["same source node"]},", then finishes at 6. Expected terminal time is ",{"tag":"code","children":["max(3,5)+1 = 6"]},"."]},{"tag":"p","children":["Inputs in different nodes do not pool. Route outputs to a shared Integration State when a later activity requires them together."]},{"tag":"h3","children":["See a resource conflict"]},{"tag":"p","children":["In a saved copy, give Start one shared request item and make both build activities require that same item. Both are individually enabled but cannot jointly consume it. Expect Resource competition ambiguity, not an arbitrary choice of a build activity."]},{"tag":"p","children":["To model an actual choice, create one routing activity that consumes a choice token and probabilistically produces a request for one route. Restore the original independent requests to model parallel work."]}]},
  {"id":"lesson-15","title":"12. Editing tools","content":[{"tag":"h2","children":["12. Editing tools"]},{"tag":"ul","children":[{"tag":"li","children":[{"tag":"strong","children":["Undo"]}," or ",{"tag":"strong","children":["Ctrl+Z"]}," on Windows/Linux, ",{"tag":"strong","children":["Cmd+Z"]}," on macOS restores model edits. A drag and a probability adjustment are each one undoable operation. Simulation settings are separate from model undo."]},{"tag":"li","children":[{"tag":"strong","children":["Probability editing"]}," adjusts other valid probabilities within the same activity proportionally. Verify the total after adding or removing outcomes, especially when fields are incomplete."]},{"tag":"li","children":[{"tag":"strong","children":["Network outline"]}," selects nodes and activities without hunting on the canvas."]},{"tag":"li","children":[{"tag":"strong","children":["Fit View"]},", zoom, pan, and drag help arrange larger networks."]},{"tag":"li","children":[{"tag":"strong","children":["Validation diagnostics"]}," can select the affected editor element. Fix missing references after deletion."]}]},{"tag":"p","children":["Model or settings edits clear previous results. ",{"tag":"strong","children":["New blank"]},", ",{"tag":"strong","children":["Load demo"]},", and successful import replace the workspace and reset its undo history; export first."]},{"tag":"h3","children":["12.1 Resize the workspace panels"]},{"tag":"p","children":["On a desktop-width window, drag the separators between ",{"tag":"strong","children":["Model"]},", ",{"tag":"strong","children":["Canvas"]},", and ",{"tag":"strong","children":["Properties"]},", or the separator above ",{"tag":"strong","children":["Analysis"]},". Widen Properties to read documentation and increase Analysis height for statistics."]},{"tag":"p","children":["For keyboard operation, Tab to a separator and use the arrow keys along its movement axis. Shift+arrow makes larger steps; Home and End move to its minimum and maximum. Use ",{"tag":"strong","children":["Reset layout"]}," in the top bar to restore defaults. Resize limits keep panels usable; narrow windows use the responsive layout rather than these desktop handles."]},{"tag":"p","children":["Panel sizes are remembered locally, with portable-host persistence across app restarts. These preferences do not save your network, do not enter model JSON or simulation RNG keys, and are separate from Undo history. Export the model or snapshot before closing even if the panels reopen at their previous sizes."]}]},
  {"id":"lesson-16","title":"13. Troubleshooting","content":[{"tag":"h2","children":["13. Troubleshooting"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Problem"]},{"tag":"th","children":["What to check"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["At least one positive consumable requirement is required"]},{"tag":"td","children":["Add an item type, add it under Requirements, and enter a quantity greater than zero"]}]},{"tag":"tr","children":[{"tag":"td","children":["Missing or multiple Start nodes"]},{"tag":"td","children":["Keep exactly one Start and put initial inventory there"]}]},{"tag":"tr","children":[{"tag":"td","children":["Incoming flow to Start"]},{"tag":"td","children":["Retarget the loop to a State buffer, as in the rework lesson"]}]},{"tag":"tr","children":[{"tag":"td","children":["Terminal has an outgoing activity"]},{"tag":"td","children":["Use a State for intermediate work; Terminal ends the realization"]}]},{"tag":"tr","children":[{"tag":"td","children":["Invalid duration"]},{"tag":"td","children":["Fill all parameters; use valid ordering and positive Beta-PERT lambda"]}]},{"tag":"tr","children":[{"tag":"td","children":["Invalid probability sum"]},{"tag":"td","children":["Complete every probability and check the activity total is 1; backend validation does not silently normalize imported values"]}]},{"tag":"tr","children":[{"tag":"td","children":["Missing item or node reference"]},{"tag":"td","children":["Correct requirements, produced items, source, or target after deletion"]}]},{"tag":"tr","children":[{"tag":"td","children":["Duplicate terminal codes"]},{"tag":"td","children":["Give each Terminal a unique Outcome code"]}]},{"tag":"tr","children":[{"tag":"td","children":["Deadlock"]},{"tag":"td","children":["Trace available items; compare all required types and quantities at each activity's single source"]}]},{"tag":"tr","children":[{"tag":"td","children":["Resource competition ambiguity"]},{"tag":"td","children":["Inspect aggregate demand across enabled activities; define explicit routing or separate consumable inputs"]}]},{"tag":"tr","children":[{"tag":"td","children":["Time/count cutoff"]},{"tag":"td","children":["Inspect loops and choose justified limits; do not assume nontermination"]}]},{"tag":"tr","children":[{"tag":"td","children":["Import rejected"]},{"tag":"td","children":["Structurally valid null drafts are accepted; malformed structure, invalid supplied values, or inconsistent/unsupported snapshots still require correction"]}]},{"tag":"tr","children":[{"tag":"td","children":["Run Simulation is disabled"]},{"tag":"td","children":["Inspect the missing-input list; choose the unknown distribution and fill all null duration/probability parameters"]}]},{"tag":"tr","children":[{"tag":"td","children":["Restored results vanish after editing"]},{"tag":"td","children":["Edits invalidate the saved report; export the snapshot before editing and rerun afterward"]}]},{"tag":"tr","children":[{"tag":"td","children":["SE or CI says Unavailable"]},{"tag":"td","children":["Check the relevant sample size; an inferential mean SD/SE/CI needs at least two observations, and extreme quantile bounds may need more"]}]},{"tag":"tr","children":[{"tag":"td","children":["Panel sizes remain but work disappears"]},{"tag":"td","children":["Panel preferences persist; model and result data still require Export JSON"]}]},{"tag":"tr","children":[{"tag":"td","children":["Editor opens but Validate/Run fails"]},{"tag":"td","children":["Verify the backend; for Docker check health and logs, for EXE keep its control window running"]}]},{"tag":"tr","children":[{"tag":"td","children":["Work disappears after refresh"]},{"tag":"td","children":["Import your last valid export; export before refreshing next time"]}]}]}]},{"tag":"p","children":["The probability sum tolerance is ",{"tag":"code","children":["1e-14"]},"; item quantities use exact decimal comparisons with no quantity epsilon. Use consistent decimal quantities rather than relying on a display rounding rule to fix a mismatch."]}]},
  {"id":"lesson-17","title":"14. Explore the complete prototype example","content":[{"tag":"h2","children":["14. Explore the complete prototype example"]},{"tag":"p","children":["Export your work, then click ",{"tag":"strong","children":["Load demo"]},". The built-in example combines everything learned:"]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Activity"]},{"tag":"th","children":["Duration"]},{"tag":"th","children":["Role"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Mechanical design"]},{"tag":"td","children":["Triangular(2, 3, 5)"]},{"tag":"td","children":["Produces a mechanical module"]}]},{"tag":"tr","children":[{"tag":"td","children":["Software build"]},{"tag":"td","children":["Uniform(3, 6)"]},{"tag":"td","children":["Produces a software build in parallel"]}]},{"tag":"tr","children":[{"tag":"td","children":["Integrate prototype"]},{"tag":"td","children":["Fixed(1)"]},{"tag":"td","children":["Consumes both outputs at Integration ready"]}]},{"tag":"tr","children":[{"tag":"td","children":["Test prototype"]},{"tag":"td","children":["Beta-PERT(1, 2, 4, lambda=4)"]},{"tag":"td","children":["Pass 0.80, retry 0.15, reject 0.05"]}]},{"tag":"tr","children":[{"tag":"td","children":["Repair prototype"]},{"tag":"td","children":["Fixed(2)"]},{"tag":"td","children":["Returns a prototype to Test ready"]}]}]}]},{"tag":"p","children":["Here retries return to testing, not to the original parallel builds. Pass and reject reach different Terminals; retry produces a repair request at Rework ready."]},{"tag":"p","children":["Validate and run using the visible demo settings. Then increase Realizations from 100 to 1000 while preserving the seed and limits. Compare outcome estimates and activity starts. More realizations reduce sampling noise but can increase runtime and memory use."]},{"tag":"p","children":["For the ideal unlimited retry process, the eventual approval probability is ",{"tag":"code","children":["0.80/(0.80+0.05) = 16/17"]},", rejection is ",{"tag":"code","children":["1/17"]},", and expected test starts are ",{"tag":"code","children":["1/0.85 = 20/17"]},". Finite run limits can introduce cutoffs, so interpret sampled results with their statuses and conditioning."]},{"tag":"p","children":["Try changing retry probability, duration uncertainty, and limits one at a time, exporting named checkpoints. Keep the completed tutorial network separate from the demo."]}]},
  {"id":"lesson-18","title":"15. Write documentation and explain certainty","content":[{"tag":"h2","children":["15. Write documentation and explain certainty"]},{"tag":"p","children":["These controls are implemented in 0.2.0. Click the element and expand its documentation section in ",{"tag":"strong","children":["Properties"]},"; full notes stay out of the main canvas. You can also select a node and use ",{"tag":"strong","children":["Associated activities and outcomes"]}," to navigate to its outgoing activity or incoming outcome."]},{"tag":"table","children":[{"tag":"thead","children":[{"tag":"tr","children":[{"tag":"th","children":["Element"]},{"tag":"th","children":["Section to expand"]},{"tag":"th","children":["Actual editor fields"]}]}]},{"tag":"tbody","children":[{"tag":"tr","children":[{"tag":"td","children":["Start, State, or Terminal node"]},{"tag":"td","children":["Node documentation"]},{"tag":"td","children":["Comments; Assumptions; Certainty level; Explanation"]}]},{"tag":"tr","children":[{"tag":"td","children":["Activity's duration"]},{"tag":"td","children":["Duration documentation"]},{"tag":"td","children":["Rationale; Assumptions; Sources / references; Certainty level"]}]},{"tag":"tr","children":[{"tag":"td","children":["Alternative outcome"]},{"tag":"td","children":["Outcome 1 documentation, Outcome 2 documentation, etc."]},{"tag":"td","children":["Rationale; Assumptions; Sources / references; Certainty level"]}]}]}]},{"tag":"p","children":[{"tag":"strong","children":["Certainty level is free text"]},", not a dropdown score, a confidence interval, or a probability. Write a useful description such as “Low — no measured timing data; process owner estimate only.” It changes no sampling, enablement, quantities, or simulation settings."]},{"tag":"h3","children":["Worked documentation example"]},{"tag":"ol","children":[{"tag":"li","children":["Select ",{"tag":"strong","children":["Uninspected component"]},", expand ",{"tag":"strong","children":["Node documentation"]},", and set Comments to “Buffer for one inspection job”; Assumptions to “Reworked components return here”; Explanation to “A State node is required because Start cannot receive outcomes”; and Certainty level to “High — follows this model's stated process.”"]},{"tag":"li","children":["Select ",{"tag":"strong","children":["Inspection"]},", expand ",{"tag":"strong","children":["Duration documentation"]},", and set Rationale to “Fixed 2 hours is a teaching simplification”; Assumptions to “No staffing queue is modeled”; Sources / references to “Tutorial example, not measured evidence”; and Certainty level to “Low for real-world prediction.”"]},{"tag":"li","children":["In the Pass outcome, expand its documentation and write Rationale “0.80 is a teaching assumption; no acceptance-rate dataset supplied.” In Fail, explain that 0.20 complements Pass. Use real source/date/sample-size information when replacing these tutorial assumptions."]}]},{"tag":"p","children":["For Beta-PERT, document why min, mode, max, and lambda were chosen, with units and exclusions. Do not present tutorial values as observations."]},{"tag":"h3","children":["Export and check"]},{"tag":"p","children":["Node and outcome text is stored under ",{"tag":"code","children":["documentation"]},"; activity timing notes are stored under ",{"tag":"code","children":["duration_documentation"]},", independently of whether a duration is selected. Notes survive distribution changes and model export/import. Unprovided or empty documentation is allowed."]},{"tag":"p","children":["Export, import in a fresh workspace, and click the same elements to check the text. Documentation does not affect the engine's draws or mathematics, but the editor conservatively clears results after model edits, including note edits. Rerun with the same model estimates, settings, and seed to check numerical repeatability."]}]},
  {"id":"lesson-19","title":"16. Keep unknown inputs as placeholders","content":[{"tag":"h2","children":["16. Keep unknown inputs as placeholders"]},{"tag":"p","children":["Null drafts are implemented. The current editor supports ",{"tag":"strong","children":["unknown duration distributions"]},", ",{"tag":"strong","children":["unknown required duration parameters"]},", and ",{"tag":"strong","children":["unknown outcome probabilities"]},". This is not permission to leave arbitrary IDs, links, requirements, or quantities malformed."]},{"tag":"h3","children":["Unknown duration"]},{"tag":"p","children":["In a draft copy of the existing Inspection model, select Inspection and choose ",{"tag":"strong","children":["Unknown — choose later"]}," in Distribution. The exported activity has:"]},{"tag":"pre","children":[{"tag":"code","children":["\"duration\": null\n"]}]},{"tag":"p","children":["If you know the distribution family but lack parameters, select it and leave the missing parameter fields blank. For example:"]},{"tag":"pre","children":[{"tag":"code","children":["\"duration\": {\"type\": \"beta-PERT\", \"min\": null, \"mode\": null, \"max\": null, \"lambda\": null}\n"]}]},{"tag":"p","children":["Or preserve a known lower bound while leaving the upper bound unknown:"]},{"tag":"pre","children":[{"tag":"code","children":["\"duration\": {\"type\": \"uniform\", \"min\": \"0\", \"max\": null}\n"]}]},{"tag":"p","children":["These are field excerpts, not standalone importable models. The full graph still needs its normal IDs, links, item declarations, positive requirements, and other structural fields."]},{"tag":"p","children":["Changing a distribution clears its numeric parameters. Duration documentation remains attached to the activity. Null means unknown, whereas explicit ",{"tag":"code","children":["0"]}," is a known zero duration. In hand-edited JSON use actual ",{"tag":"code","children":["null"]},", not ",{"tag":"code","children":["\"null\""]},", an empty numeric string, or an omitted required key."]},{"tag":"h3","children":["Unknown probability"]},{"tag":"p","children":["Clear Pass and Fail's Probability fields. Each outcome exports ",{"tag":"code","children":["\"probability\": null"]},". Both branches remain visible; no 50/50 probability is inferred. While the set has any unknown values, editing one changes only that value, including when filling the last unknown. Then validate the completed sum before relying on proportional editing of a complete set."]},{"tag":"h3","children":["Validate, save, and complete a draft"]},{"tag":"ol","children":[{"tag":"li","children":["Leave Inspection's duration and probabilities unknown and add notes explaining the missing evidence."]},{"tag":"li","children":["Click ",{"tag":"strong","children":["Validate"]},". For an otherwise valid graph, expect ",{"tag":"strong","children":["Draft valid · Complete missing inputs before simulation"]},", plus missing-input diagnostics."]},{"tag":"li","children":["Export as ",{"tag":"code","children":["qc-04-incomplete-draft.json"]},". Because editing cleared the prior result, this is model-only JSON."]},{"tag":"li","children":["Import the file and inspect the same placeholders and documentation. The model reopens without estimating its unknowns."]},{"tag":"li","children":[{"tag":"strong","children":["Run Simulation"]}," remains disabled while the UI detects missing inputs. Use the missing-input list to select the affected element. The backend also rejects incomplete simulation requests; bypassing the UI does not make the draft executable."]},{"tag":"li","children":["Select Fixed ",{"tag":"code","children":["2"]},", enter Pass ",{"tag":"code","children":["0.80"]}," and Fail ",{"tag":"code","children":["0.20"]},", verify Probability total 1, validate again, enter/check all run settings, and simulate."]}]},{"tag":"p","children":["Draft validity and readiness are different. Invalid supplied values still fail: a negative duration, probability 1.2, broken node reference, or inconsistent known bounds is an error. For example, min=3 and max=2 remain invalid even if mode is null. Null preserves a gap in your evidence; it does not excuse known contradictions."]},{"tag":"p","children":["The mathematical schema is still ",{"tag":"code","children":["0.1"]},", with additive reader support for documentation/null drafts. Older builds may reject those files. Use the 0.2.0 preview when sharing these drafts."]}]},
  {"id":"lesson-20","title":"17. Use this interactive guide","content":[{"tag":"h2","children":["17. Use the in-app tutorial"]},{"tag":"p","children":["Learn / Tutorial opens an isolated practice workspace. Return to my project restores your original project, settings, undo history and results. Export both workspaces before refreshing; neither has model autosave."]},{"tag":"p","children":["Lesson navigation preserves practice work. Loading a new exercise asks before replacing it. The actual editor uses canonical model JSON and the real backend; standalone practice files are not GERT networks."]},{"tag":"p","children":["Reading lessons have a completion checkbox. Exercise lessons require Check exercise against current inputs and backend responses. Progress records completed work, not a guarantee about later edits. Only lesson progress is saved in separate browser storage. Reset tutorial progress clears those records alone."]},{"tag":"p","children":["Find control highlights the real editor. Node and activity guides select the element first. Read the full lesson with Show lesson text. Tab reaches every control; arrow keys, Home and End navigate lesson buttons."]}]},
  {"id":"lesson-21","title":"References and verification scope","content":[{"tag":"h2","children":["References and verification scope"]},{"tag":"p","children":["Base source was rechecked against main: ",{"tag":"code","children":["52fcd732787d5829d923bf2178594de21704b2dc"]},". Historical Windows preview v0.2.0 used application source ",{"tag":"code","children":["e4d0b26b281803a520c0525fa8f62011b55219f2"]},". Current engine 0.1.1 uses ",{"tag":"code","children":["gert-v2-py312-sha256-mt19937-crmath1"]},"."]},{"tag":"p","children":["MODEL.md governs mathematics; PRODUCT.md governs product behavior. This tutorial changes neither engine semantics nor RNG. The Windows workflow source confirms manual main builds and release-triggered uploads, with no push trigger. Live release metadata access was blocked by the environment proxy."]},{"tag":"p","children":["See docs/INTERACTIVE_TUTORIAL_REVIEW.md for unit, backend and browser evidence and actual screenshots. Linux checks do not certify a Windows executable or clean-machine acceptance."]}]},
];
